result.output:
1	/* DataTraceMind design system, shared by the incident console and the Scenario Lab.
2	   Colours are roles, defined once per mode. Status colours always travel with
3	   a glyph and a label; chart series colours are never reused for status. */
4	
5	:root {
6	  color-scheme: light;
7	  --font-sans: "Inter", ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
8	  --font-mono: ui-monospace, "SF Mono", SFMono-Regular, "JetBrains Mono", Menlo, Consolas, monospace;
9	
10	  --page: #f4f5f7;
11	  --surface: #ffffff;
12	  --surface-sunken: #f3f4f7;
13	  --surface-hover: #f7f8fa;
14	  --border: #e3e6eb;
15	  --border-strong: #cfd4dc;
16	  --text: #131722;
17	  --text-secondary: #485060;
18	  --text-muted: #6a7282;
19	  --accent: #2557d6;
20	  --accent-hover: #1d49b8;
21	  --accent-ink: #ffffff;
22	  --accent-wash: #e9effd;
23	
24	  /* Navigation chrome keeps its own dark surface in both modes. */
25	  --nav: #101624;
26	  --nav-raised: #1a2233;
27	  --nav-border: #242d40;
28	  --nav-text: #c3cad8;
29	  --nav-text-muted: #8791a6;
30	  --nav-text-strong: #ffffff;
31	  --nav-accent: #7ea6ff;
32	
33	  --series-1: #2a78d6;
34	  --series-2: #eb6834;
35	
36	  --good: #0ca30c;
37	  --good-ink: #075c07;
38	  --good-wash: #e6f5e6;
39	  --warning: #fab219;
40	  --warning-ink: #6f4a00;
41	  --warning-wash: #fdf1d3;
42	  --serious: #ec835a;
43	  --serious-ink: #8a3310;
44	  --serious-wash: #fce9e0;
45	  --critical: #d03b3b;
46	  --critical-ink: #8f1f1f;
47	  --critical-wash: #fae3e3;
48	  --neutral-wash: #eceef2;
49	  --active-wash: #e9effd;
50	  --diff-add: #e3f4e3;
51	  --diff-del: #fae3e3;
52	
53	  --shadow-sm: 0 1px 2px rgb(16 22 36 / 5%);
54	  --shadow-md: 0 6px 20px rgb(16 22 36 / 12%);
55	  --radius: 8px;
56	  --radius-sm: 6px;
57	  --sidebar-width: 236px;
58	  --topbar-height: 52px;
59	}
60	
61	@media (prefers-color-scheme: dark) {
62	  :root {
63	    color-scheme: dark;
64	    --page: #0c0f15;
65	    --surface: #151a23;
66	    --surface-sunken: #1c222d;
67	    --surface-hover: #1a202a;
68	    --border: #272e3b;
69	    --border-strong: #38414f;
70	    --text: #f1f3f7;
71	    --text-secondary: #b9c0cc;
72	    --text-muted: #8b94a4;
73	    --accent: #7ea6ff;
74	    --accent-hover: #9bbaff;
75	    --accent-ink: #0c0f15;
76	    --accent-wash: #17233f;
77	
78	    --nav: #0a0d13;
79	    --nav-raised: #151a23;
80	    --nav-border: #1e2430;
81	
82	    --series-1: #3987e5;
83	    --series-2: #d95926;
84	
85	    --good-ink: #7fdc7f;
86	    --good-wash: #12301a;
87	    --warning-ink: #fdd27a;
88	    --warning-wash: #3a2c08;
89	    --serious-ink: #f4b095;
90	    --serious-wash: #3b2015;
91	    --critical-ink: #f29b9b;
92	    --critical-wash: #3d1717;
93	    --neutral-wash: #232a36;
94	    --active-wash: #17233f;
95	    --diff-add: #14301a;
96	    --diff-del: #3d1717;
97	
98	    --shadow-sm: none;
99	    --shadow-md: 0 6px 20px rgb(0 0 0 / 45%);
100	  }
101	}
102	
103	* { box-sizing: border-box; }
104	
105	html { -webkit-text-size-adjust: 100%; }
106	
107	body {
108	  margin: 0;
109	  background: var(--page);
110	  color: var(--text);
111	  font: 13.5px/1.5 var(--font-sans);
112	  -webkit-font-smoothing: antialiased;
113	  font-feature-settings: "cv11", "ss01";
114	}
115	
116	h1, h2, h3, h4, p { margin: 0; }
117	h1 { font-size: 20px; font-weight: 650; letter-spacing: -0.01em; line-height: 1.3; }
118	h2 { font-size: 14px; font-weight: 650; letter-spacing: -0.003em; }
119	h3 { font-size: 13px; font-weight: 650; margin: 20px 0 8px; display: flex; flex-wrap: wrap; align-items: center; gap: 8px; }
120	h4 { font-size: 12px; font-weight: 600; margin: 14px 0 6px; color: var(--text-secondary); }
121	code, pre, .json, .diff, .mono { font-family: var(--font-mono); font-size: 12px; }
122	code { background: var(--surface-sunken); border: 1px solid var(--border); padding: 0 5px; border-radius: 4px; overflow-wrap: anywhere; }
123	a { color: var(--accent); text-decoration: none; }
124	a:hover { text-decoration: underline; }
125	ul, ol { margin: 0; padding: 0; }
126	
127	.muted { color: var(--text-muted); }
128	.secondary { color: var(--text-secondary); }
129	.right { text-align: right; }
130	.nowrap { white-space: nowrap; }
131	.empty { color: var(--text-muted); padding: 12px 0; }
132	.spacer { flex: 1; }
133	.icon { flex: none; display: block; }
134	.stack { display: flex; flex-direction: column; gap: 16px; }
135	.row { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; }
136	.columns { display: grid; grid-template-columns: repeat(auto-fit, minmax(380px, 1fr)); gap: 16px; }
137	.columns > * { min-width: 0; }
138	.eyebrow { font-size: 11px; font-weight: 650; letter-spacing: 0.06em; text-transform: uppercase; color: var(--text-muted); }
139	.sr-only { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }
140	
141	/* --- Application shell ------------------------------------------------------ */
142	
143	.shell { display: grid; grid-template-columns: var(--sidebar-width) minmax(0, 1fr); min-height: 100vh; }
144	
145	.sidebar {
146	  position: sticky; top: 0; height: 100vh; overflow-y: auto;
147	  display: flex; flex-direction: column; gap: 4px;
148	  background: var(--nav); color: var(--nav-text); border-right: 1px solid var(--nav-border);
149	  padding: 14px 12px 12px;
150	}
151	.brand { display: flex; align-items: center; gap: 10px; padding: 2px 6px 14px; color: var(--nav-text-strong); }
152	.brand:hover { text-decoration: none; }
153	.brand-mark { flex: none; border-radius: 7px; }
154	.brand-name { font-size: 14.5px; font-weight: 650; letter-spacing: -0.01em; line-height: 1.2; }
155	.brand-tag { font-size: 11px; color: var(--nav-text-muted); line-height: 1.3; }
156	
157	.nav-label { font-size: 10.5px; font-weight: 650; letter-spacing: 0.08em; text-transform: uppercase; color: var(--nav-text-muted); padding: 14px 8px 6px; }
158	.nav-item {
159	  appearance: none; border: 0; background: none; width: 100%; text-align: left; cursor: pointer;
160	  display: flex; align-items: center; gap: 10px; padding: 7px 8px; border-radius: var(--radius-sm);
161	  font: inherit; font-weight: 500; color: var(--nav-text);
162	}
163	.nav-item:hover { background: var(--nav-raised); color: var(--nav-text-strong); text-decoration: none; }
164	.nav-item.active { background: var(--nav-raised); color: var(--nav-text-strong); box-shadow: inset 2px 0 0 var(--nav-accent); }
165	.nav-item .icon { opacity: 0.85; }
166	.nav-item .nav-trailing { margin-left: auto; display: inline-flex; align-items: center; opacity: 0.7; }
167	.nav-count {
168	  margin-left: auto; min-width: 20px; text-align: center; font-size: 11px; font-weight: 650; line-height: 18px;
169	  padding: 0 6px; border-radius: 999px; background: #c2452c; color: #ffffff;
170	}
171	.nav-hint { font-size: 11.5px; line-height: 1.45; color: var(--nav-text-muted); padding: 2px 8px 0; }
172	
173	.sidebar-foot { margin-top: auto; padding-top: 12px; }
174	.agent-card { border: 1px solid var(--nav-border); background: var(--nav-raised); border-radius: var(--radius); padding: 10px 12px; font-size: 12px; }
175	.agent-card-title { display: flex; align-items: center; gap: 8px; font-weight: 600; color: var(--nav-text-strong); }
176	.agent-card dl { margin: 8px 0 0; display: grid; grid-template-columns: auto 1fr; gap: 2px 10px; }
177	.agent-card dt { color: var(--nav-text-muted); }
178	.agent-card dd { margin: 0; text-align: right; overflow-wrap: anywhere; }
179	.agent-card p { margin-top: 6px; color: var(--nav-text-muted); line-height: 1.4; }
180	
181	.dot { flex: none; width: 8px; height: 8px; border-radius: 50%; background: var(--text-muted); display: inline-block; }
182	.dot-good { background: var(--good); }
183	.dot-warning { background: var(--warning); }
184	.dot-critical { background: var(--critical); }
185	.dot-live { background: var(--good); box-shadow: 0 0 0 0 rgb(12 163 12 / 45%); animation: pulse 1.8s ease-out infinite; }
186	@keyframes pulse { to { box-shadow: 0 0 0 7px rgb(12 163 12 / 0%); } }
187	
188	.main { min-width: 0; display: flex; flex-direction: column; }
189	.topbar {
190	  position: sticky; top: 0; z-index: 20; height: var(--topbar-height);
191	  display: flex; align-items: center; gap: 12px; padding: 0 28px;
192	  background: var(--surface); border-bottom: 1px solid var(--border);
193	}
194	.crumbs { display: flex; align-items: center; gap: 6px; min-width: 0; font-size: 13px; color: var(--text-muted); }
195	.crumbs button { appearance: none; border: 0; background: none; padding: 0; font: inherit; color: inherit; cursor: pointer; }
196	.crumbs button:hover { color: var(--text); }
197	.crumbs .crumb-current { color: var(--text); font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
198	.topbar-right { margin-left: auto; display: flex; align-items: center; gap: 10px; }
199	.topbar-meta { font-size: 12px; color: var(--text-muted); white-space: nowrap; }
200	.access-code { width: 160px; }
201	
202	.content { width: 100%; max-width: 1360px; margin: 0 auto; padding: 24px 28px 72px; }
203	.page-head { display: flex; flex-wrap: wrap; align-items: flex-end; justify-content: space-between; gap: 12px 24px; margin-bottom: 18px; }
204	.page-head p { margin-top: 3px; color: var(--text-secondary); max-width: 86ch; }
205	.page-actions { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; }
206	
207	@media (max-width: 980px) {
208	  .shell { grid-template-columns: minmax(0, 1fr); }
209	  .sidebar { position: static; height: auto; flex-direction: row; align-items: center; overflow-x: auto; padding: 8px 12px; gap: 2px; }
210	  .brand { padding: 0 10px 0 4px; }
211	  .brand-tag, .nav-label, .nav-hint, .sidebar-foot { display: none; }
212	  .sidebar nav { display: flex; gap: 2px; }
213	  .nav-item { width: auto; white-space: nowrap; }
214	  .nav-item .nav-count, .nav-item .nav-trailing { margin-left: 2px; }
215	  .nav-item.active { box-shadow: inset 0 -2px 0 var(--nav-accent); }
216	  .topbar { padding: 0 16px; }
217	  .content { padding: 18px 16px 56px; }
218	}
219	
220	/* --- Cards, buttons, form controls ---------------------------------------- */
221	
222	.card { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius); box-shadow: var(--shadow-sm); min-width: 0; }
223	.card-head { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: flex-start; gap: 8px 16px; padding: 14px 18px 0; }
224	.card-head > :first-child { flex: 1 1 240px; min-width: 0; }
225	.card-head p { max-width: 92ch; margin-top: 2px; font-size: 12.5px; }
226	.card-actions { flex: none; display: flex; flex-wrap: wrap; align-items: center; gap: 8px; min-height: 24px; }
227	.card-body { padding: 14px 18px 16px; }
228	.card-head + .card-body { padding-top: 12px; }
229	.card-flush > .card-body { padding-left: 0; padding-right: 0; padding-bottom: 4px; }
230	.card-flush > .card-body:first-child { padding-top: 0; }
231	.card-flush > .card-body:first-child .table th { border-top: 0; }
232	.card-flush > .card-body:first-child .table tr:first-child th:first-child { border-top-left-radius: var(--radius); }
233	.card-flush > .card-body:first-child .table tr:first-child th:last-child { border-top-right-radius: var(--radius); }
234	.card-flush .empty { padding: 12px 18px; }
235	
236	.button {
237	  appearance: none; font: inherit; font-weight: 600; cursor: pointer; white-space: nowrap;
238	  display: inline-flex; align-items: center; justify-content: center; gap: 7px;
239	  border: 1px solid var(--border-strong); background: var(--surface); color: var(--text);
240	  height: 32px; padding: 0 12px; border-radius: var(--radius-sm); box-shadow: var(--shadow-sm);
241	}
242	.button:hover:not(:disabled) { background: var(--surface-hover); text-decoration: none; }
243	.button:disabled { opacity: 0.5; cursor: not-allowed; box-shadow: none; }
244	.button-primary { background: var(--accent); border-color: var(--accent); color: var(--accent-ink); }
245	.button-primary:hover:not(:disabled) { background: var(--accent-hover); border-color: var(--accent-hover); }
246	.button-danger { color: var(--critical-ink); border-color: var(--critical); }
247	.button-danger:hover:not(:disabled) { background: var(--critical-wash); }
248	.button-ghost { border-color: transparent; background: none; box-shadow: none; color: var(--text-secondary); }
249	.button-ghost:hover:not(:disabled) { background: var(--surface-sunken); color: var(--text); }
250	.button-large { height: 38px; padding: 0 16px; font-size: 14px; }
251	.link { appearance: none; border: 0; background: none; padding: 0; font: inherit; color: var(--accent); cursor: pointer; }
252	.link:hover { text-decoration: underline; }
253	
254	input, select {
255	  font: inherit; color: var(--text); background: var(--surface); border: 1px solid var(--border-strong);
256	  border-radius: var(--radius-sm); height: 32px; padding: 0 10px;
257	}
258	input::placeholder { color: var(--text-muted); }
259	input[type="checkbox"] { height: auto; padding: 0; accent-color: var(--accent); }
260	:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
261	.field-inline { display: inline-flex; align-items: center; gap: 8px; color: var(--text-secondary); font-size: 12.5px; }
262	.search { position: relative; display: inline-flex; align-items: center; }
263	.search .icon { position: absolute; left: 9px; color: var(--text-muted); pointer-events: none; }
264	.search input { padding-left: 30px; width: 240px; }
265	
266	.segmented { display: inline-flex; padding: 2px; gap: 2px; background: var(--surface-sunken); border: 1px solid var(--border); border-radius: var(--radius-sm); }
267	.segmented button {
268	  appearance: none; border: 0; background: none; cursor: pointer; font: inherit; font-weight: 550; color: var(--text-secondary);
269	  padding: 4px 11px; border-radius: 4px; white-space: nowrap; display: inline-flex; align-items: center; gap: 6px;
270	}
271	.segmented button:hover:not(:disabled) { color: var(--text); }
272	.segmented button:disabled { cursor: not-allowed; opacity: 0.6; }
273	.segmented button[aria-pressed="true"] { background: var(--surface); color: var(--text); box-shadow: var(--shadow-sm), 0 0 0 1px var(--border); }
274	.segmented .count { font-size: 11px; color: var(--text-muted); font-weight: 600; }
275	
276	/* --- Badges, tags, notes --------------------------------------------------- */
277	
278	.badge {
279	  display: inline-flex; align-items: center; gap: 5px; white-space: nowrap; vertical-align: middle;
280	  font-size: 11.5px; font-weight: 600; line-height: 1.45; padding: 1px 8px 1px 6px; border-radius: 999px;
281	  background: var(--neutral-wash); color: var(--text-secondary);
282	}
283	.badge-glyph { font-size: 9.5px; width: 11px; text-align: center; }
284	.tone-good { background: var(--good-wash); color: var(--good-ink); }
285	.tone-warning { background: var(--warning-wash); color: var(--warning-ink); }
286	.tone-serious { background: var(--serious-wash); color: var(--serious-ink); }
287	.tone-critical { background: var(--critical-wash); color: var(--critical-ink); }
288	.tone-active { background: var(--active-wash); color: var(--accent); }
289	.tone-active .badge-glyph { animation: spin 1.6s linear infinite; }
290	@keyframes spin { to { transform: rotate(360deg); } }
291	@media (prefers-reduced-motion: reduce) { .tone-active .badge-glyph, .dot-live { animation: none; } }
292	
293	.tag {
294	  display: inline-block; font-size: 11px; font-weight: 600; line-height: 1.5; padding: 0 6px; border-radius: 4px;
295	  background: var(--surface-sunken); color: var(--text-secondary); border: 1px solid var(--border);
296	  text-decoration: none; margin-right: 4px; white-space: nowrap;
297	}
298	.tag-strong { color: var(--text); font-family: var(--font-mono); }
299	summary > .tag:last-child { margin-left: 8px; margin-right: 0; }
300	.status-text { font-size: 11.5px; font-weight: 600; color: var(--text-secondary); letter-spacing: 0.02em; }
301	.id { font-family: var(--font-mono); font-size: 12px; font-weight: 600; }
302	
303	.note { margin: 12px 0; padding: 10px 12px; border-radius: var(--radius-sm); background: var(--surface-sunken); border: 1px solid var(--border); display: flex; flex-wrap: wrap; gap: 6px 12px; align-items: center; }
304	.note-error { background: var(--critical-wash); border-color: transparent; color: var(--critical-ink); justify-content: space-between; }
305	.note-info { background: var(--accent-wash); border-color: transparent; color: var(--text); }
306	
307	.banner {
308	  display: flex; flex-wrap: wrap; justify-content: space-between; align-items: center; gap: 12px 20px;
309	  background: var(--surface); border: 1px solid var(--border); border-left: 4px solid var(--serious);
310	  border-radius: var(--radius); padding: 14px 18px; box-shadow: var(--shadow-sm);
311	}
312	.banner-critical { border-left-color: var(--critical); }
313	.banner-title { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; font-weight: 650; }
314	.banner p { margin-top: 5px; color: var(--text-secondary); max-width: 100ch; }
315	
316	/* --- KPI tiles -------------------------------------------------------------- */
317	
318	.kpis { display: grid; grid-template-columns: repeat(auto-fit, minmax(250px, 1fr)); gap: 16px; }
319	.kpi { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius); padding: 14px 18px 16px; box-shadow: var(--shadow-sm); min-width: 0; display: flex; flex-direction: column; }
320	.kpi-label { display: flex; align-items: center; gap: 7px; font-size: 12px; font-weight: 600; color: var(--text-secondary); }
321	.kpi-label .icon { color: var(--text-muted); }
322	.kpi-value { font-size: 26px; font-weight: 650; letter-spacing: -0.02em; line-height: 1.2; margin: 8px 0 8px; overflow-wrap: anywhere; }
323	.kpi-value-text { font-size: 19px; letter-spacing: -0.01em; display: flex; align-items: center; gap: 9px; margin: 11px 0 10px; }
324	/* The foot reserves two lines, so the breakdown starts at the same height in every tile. */
325	.kpi-foot { display: flex; flex-wrap: wrap; align-items: center; align-content: flex-start; gap: 6px 10px; font-size: 12px; min-height: 46px; }
326	.kpi-error { margin-top: 8px; font-size: 12px; color: var(--critical-ink); overflow-wrap: anywhere; }
327	.kpi-breakdown { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; margin: 14px 0 0; padding-top: 12px; border-top: 1px solid var(--border); }
328	.kpi-breakdown dt { font-size: 11.5px; color: var(--text-muted); }
329	.kpi-breakdown dd { margin: 0; font-size: 12.5px; overflow-wrap: anywhere; }
330	.kpi-breakdown .kpi-differs { color: var(--critical-ink); font-weight: 600; }
331	
332	/* --- Tables ---------------------------------------------------------------- */
333	
334	.table-scroll { overflow-x: auto; }
335	.table { width: 100%; border-collapse: collapse; font-size: 12.5px; }
336	.table th {
337	  text-align: left; font-weight: 600; color: var(--text-muted); font-size: 11px; letter-spacing: 0.04em; text-transform: uppercase;
338	  padding: 8px 12px; background: var(--surface-sunken); border-top: 1px solid var(--border); border-bottom: 1px solid var(--border); white-space: nowrap;
339	}
340	.table td { padding: 9px 12px; border-bottom: 1px solid var(--border); vertical-align: top; }
341	.table tr:last-child td { border-bottom: 0; }
342	.table th:first-child, .table td:first-child { padding-left: 18px; }
343	.table th:last-child, .table td:last-child { padding-right: 18px; }
344	.table.numeric td, .table.numeric th { font-variant-numeric: tabular-nums; }
345	.table.clickable tbody tr { cursor: pointer; }
346	.table.clickable tbody tr:hover td { background: var(--surface-hover); }
347	/* Identifiers in a table cell stay on one line; the cell scrolls with the table instead. */
348	.table td > code { overflow-wrap: normal; white-space: nowrap; }
349	.table .right { text-align: right; }
350	.table .row-strong td { font-weight: 600; }
351	.differs { color: var(--critical-ink); font-weight: 600; }
352	.table-inset th:first-child, .table-inset td:first-child { padding-left: 12px; }
353	.table-inset th:last-child, .table-inset td:last-child { padding-right: 12px; }
354	.table-inset { border: 1px solid var(--border); border-radius: var(--radius-sm); border-collapse: separate; border-spacing: 0; overflow: hidden; }
355	.table-inset th { border-top: 0; }
356	.cell-clip { max-width: 520px; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
357	.feed-totals { padding: 0 18px 10px; font-size: 12px; }
358	.audit-details { display: flex; flex-wrap: wrap; gap: 2px 12px; font-size: 12px; overflow-wrap: anywhere; }
359	
360	/* --- Chart ----------------------------------------------------------------- */
361	
