1	// The incident console: is the data trustworthy, and if not, what is being done about it.
2	// Injecting faults and driving the demo environment live in a separate page, the Scenario Lab.
3	import { useEffect, useState } from "react";
4	import { getAccessCode, setAccessCode, usePoll } from "./api.js";
5	import { ago } from "./format.js";
6	import Audit from "./components/Audit.jsx";
7	import { AccessCode, Badge, ErrorNote, TRUST_TEXT } from "./components/common.jsx";
8	import { BrandMark, Icon } from "./components/icons.jsx";
9	import Incidents from "./components/Incident.jsx";
10	import Overview from "./components/Overview.jsx";
11	
12	const LAB_URL = "/lab/";
13	const PAGES = [
14	  { key: "overview", label: "Overview", icon: "activity" },
15	  { key: "incidents", label: "Incidents", icon: "alert" },
16	  { key: "audit", label: "Audit log", icon: "list" },
17	];
18	
19	// The view lives in the URL hash (#/incidents/INC-0001) so a reload or a
20	// shared link lands on the same page.
21	function readRoute() {
22	  const [page, id] = window.location.hash.replace(/^#\/?/, "").split("/");
23	  return { page: PAGES.some((p) => p.key === page) ? page : "overview", id: id || null };
24	}
25	
26	function AgentCard({ agent }) {
27	  if (!agent) return null;
28	  const state = !agent.available ? "warning" : "good";
29	  return (
30	    <div className="agent-card">
31	      <div className="agent-card-title">
32	        <span className={`dot ${agent.investigation_running ? "dot-live" : `dot-${state}`}`} aria-hidden="true" />
33	        {agent.available ? (agent.investigation_running ? "Agent investigating" : "Agent available") : "Agent unavailable"}
34	      </div>
35	      {agent.available ? (
36	        <dl>
37	          <dt>Model</dt>
38	          <dd>{agent.model}</dd>
39	          <dt>Workflow</dt>
40	          <dd>{agent.workflow_version}</dd>
41	          <dt>Limit</dt>
42	          <dd>{agent.limits.per_hour} runs / hour</dd>
43	        </dl>
44	      ) : (
45	        <p>{agent.detail}</p>
46	      )}
47	    </div>
48	  );
49	}
50	
51	export default function App() {
52	  const [route, setRoute] = useState(readRoute);
53	  const [code, setCode] = useState(getAccessCode);
54	  const metrics = usePoll("/metrics/summary", 2500);
55	  const agent = usePoll("/agent/status", 5000);
56	
57	  useEffect(() => {
58	    // The lab used to be a tab of this page; old links to it still work.
59	    if (/^#\/?lab\b/.test(window.location.hash)) window.location.replace(LAB_URL);
60	    const onHash = () => setRoute(readRoute());
61	    window.addEventListener("hashchange", onHash);
62	    return () => window.removeEventListener("hashchange", onHash);
63	  }, []);
64	
65	  const go = (page, id) => {
66	    window.location.hash = id ? `/${page}/${id}` : `/${page}`;
67	    window.scrollTo(0, 0);
68	  };
69	  const refreshAll = () => {
70	    metrics.refresh();
71	    agent.refresh();
72	  };
73	
74	  const activeIncident = metrics.data?.active_incident;
75	  const trust = metrics.data?.trust;
76	  const pipeline = metrics.data?.pipeline;
77	  const current = PAGES.find((p) => p.key === route.page);
78	
