269	export default function LabApp() {
270	  const [code, setCode] = useState(getAccessCode);
271	  const [confirmingReset, setConfirmingReset] = useState(false);
272	  const lab = usePoll("/scenarios", 3000);
273	  const metrics = usePoll("/metrics/summary", 2500);
274	  const traffic = usePoll("/demo/traffic", 2000);
275	  const live = usePoll("/transactions/live?limit=6", 2000);
276	  const incidents = usePoll("/incidents", 3000);
277	  const agent = usePoll("/agent/status", 10000);
278	  const resetAction = useAction();
279	  const injectAction = useAction();
280	
281	  // A server started before this page was built answers without the fields
282	  // the lab needs; say so instead of failing on the first missing one.
283	  const outdatedApi = Boolean(lab.data) && !lab.data.environment;
284	  const active = lab.data?.active;
285	  // Whatever is unresolved right now, and the incident this scenario caused.
286	  // An injection made before reports were kept has no report; the open
287	  // incident is then the one it caused.
288	  const openIncident = metrics.data?.active_incident;
289	  const incidentId = active?.scenario_id ? (active.injection_report?.incident_id ?? openIncident?.incident_id) : null;
290	  const incident = incidentId ? incidents.data?.find((row) => row.incident_id === incidentId) : null;
291	  const activeScenario = lab.data?.scenarios.find((s) => s.scenario_id === active?.scenario_id);
292	  const phase = phaseOf(active, incident, activeScenario);
293	  const strayIncident = phase === "baseline" ? openIncident : null;
294	
295	  const refreshAll = () => Promise.all([lab, metrics, traffic, live, incidents].map((poll) => poll.refresh()));
296	
297	  // Reset wipes every incident, so it takes two clicks; the second must come
298	  // within a few seconds or the button returns to its first state.
299	  const reset = async () => {
300	    // Once a run has reached its end there is nothing in progress to lose.
301	    if (!confirmingReset && !FINISHED.has(phase)) {
302	      setConfirmingReset(true);
303	      window.setTimeout(() => setConfirmingReset(false), 4000);
304	      return;
305	    }
306	    setConfirmingReset(false);
307	    await resetAction.run(() => api("/demo/reset", { method: "POST" }));
308	    await refreshAll();
