1	// Daily net revenue: what the source implies versus what analytics reports.
2	//
3	// Two series on one axis. Where the pipeline is correct the lines coincide, so
4	// days on which they differ get a marker: the gap is the story, and it must be
5	// findable without comparing two overlapping strokes.
6	import { useMemo, useRef, useState } from "react";
7	import { compactMoney, money, shortDate, signedMoney } from "../format.js";
8	
9	// Close to the size the chart is drawn at, so axis text keeps its type size.
10	const WIDTH = 1040;
11	const HEIGHT = 270;
12	const MARGIN = { top: 16, right: 24, bottom: 30, left: 58 };
13	const SERIES = [
14	  { key: "source_net", label: "Source-derived (contract)", className: "series-1" },
15	  { key: "analytics_net", label: "Analytics daily_revenue", className: "series-2" },
16	];
17	
18	function niceCeiling(value) {
19	  if (value <= 0) return 1;
20	  const magnitude = 10 ** Math.floor(Math.log10(value));
21	  const step = [1, 2, 2.5, 5, 10].find((m) => m * magnitude >= value);
22	  return step * magnitude;
23	}
24	
25	export default function RevenueChart({ daily, currency, tolerance = 0.01 }) {
26	  const rows = useMemo(() => daily.filter((d) => d.currency === currency), [daily, currency]);
27	  const [hover, setHover] = useState(null);
28	  const [showTable, setShowTable] = useState(false);
29	  const frame = useRef(null);
30	
31	  if (rows.length < 2) return <p className="empty">Not enough days of data to chart yet.</p>;
32	
33	  const innerWidth = WIDTH - MARGIN.left - MARGIN.right;
34	  const innerHeight = HEIGHT - MARGIN.top - MARGIN.bottom;
35	  const top = niceCeiling(Math.max(...rows.flatMap((r) => [r.source_net, r.analytics_net])));
36	  const x = (index) => MARGIN.left + (index / (rows.length - 1)) * innerWidth;
37	  const y = (value) => MARGIN.top + innerHeight - (Math.max(value, 0) / top) * innerHeight;
38	  const path = (key) => rows.map((r, i) => `${i === 0 ? "M" : "L"}${x(i).toFixed(1)},${y(r[key]).toFixed(1)}`).join(" ");
39	  const ticks = [0, 0.25, 0.5, 0.75, 1].map((share) => share * top);
40	  const labelEvery = Math.ceil(rows.length / 8);
41	  const differs = (row) => Math.abs(row.analytics_net - row.source_net) > tolerance;
42	  const mismatched = rows.filter(differs).length;
43	
44	  function onMove(event) {
45	    const box = frame.current.getBoundingClientRect();
46	    const position = ((event.clientX - box.left) / box.width) * WIDTH;
47	    const index = Math.round(((position - MARGIN.left) / innerWidth) * (rows.length - 1));
48	    setHover(Math.min(rows.length - 1, Math.max(0, index)));
49	  }
50	
51	  const active = hover === null ? null : rows[hover];
52	  const tooltipLeft = hover === null ? 0 : (x(hover) / WIDTH) * 100;
53	
54	  return (
55	    <div className="chart">
56	      <div className="chart-legend">
57	        {SERIES.map((series) => (
58	          <span key={series.key} className="legend-item">
59	            <span className={`legend-line ${series.className}`} aria-hidden="true" />
60	            {series.label}
61	          </span>
62	        ))}
63	        <span className="legend-item">
64	          <span className="legend-dot series-2" aria-hidden="true" />
65	          Day where they differ
66	        </span>
67	        <button type="button" className="link chart-toggle" onClick={() => setShowTable((v) => !v)}>
68	          {showTable ? "Show chart" : "Show as table"}
69	        </button>
70	      </div>
71	
72	      {showTable ? (
73	        <div className="table-scroll">
74	          <table className="table table-inset numeric">
75	            <thead>
76	              <tr>
77	                <th>Day</th>
78	                <th className="right">Source-derived</th>
79	                <th className="right">Analytics</th>
80	                <th className="right">Difference</th>
81	              </tr>
82	            </thead>
83	            <tbody>
84	              {[...rows].reverse().map((row) => (
85	                <tr key={row.date}>
86	                  <td>{shortDate(row.date)}</td>
87	                  <td className="right">{money(row.source_net, currency)}</td>
88	                  <td className="right">{money(row.analytics_net, currency)}</td>
89	                  <td className="right">
90	                    {differs(row) ? signedMoney(row.analytics_net - row.source_net, currency) : "matches"}
91	                  </td>
92	                </tr>
93	              ))}
94	            </tbody>
95	          </table>
96	        </div>
97	      ) : (
98	        <div className="chart-frame" ref={frame}>
99	          <svg
100	            viewBox={`0 0 ${WIDTH} ${HEIGHT}`}
101	            role="img"
102	            aria-label={`Daily net revenue in ${currency}, source-derived versus analytics. ${mismatched} of ${rows.length} days differ.`}
103	            onPointerMove={onMove}
104	            onPointerLeave={() => setHover(null)}
105	          >
106	            {ticks.map((tick) => (
107	              <g key={tick}>
108	                <line className="grid" x1={MARGIN.left} x2={WIDTH - MARGIN.right} y1={y(tick)} y2={y(tick)} />
109	                <text className="axis" x={MARGIN.left - 8} y={y(tick)} textAnchor="end" dominantBaseline="middle">
110	                  {compactMoney(tick, currency)}
111	                </text>
112	              </g>
113	            ))}
114	            {rows.map(
115	              (row, index) =>
116	                (index % labelEvery === 0 || index === rows.length - 1) && (
117	                  <text key={row.date} className="axis" x={x(index)} y={HEIGHT - 8} textAnchor="middle">
118	                    {shortDate(row.date)}
119	                  </text>
120	                ),
121	            )}
122	            {active && <line className="crosshair" x1={x(hover)} x2={x(hover)} y1={MARGIN.top} y2={MARGIN.top + innerHeight} />}
123	            {SERIES.map((series) => (
124	              <path key={series.key} className={`line ${series.className}`} d={path(series.key)} />
125	            ))}
126	            {rows.map(
127	              (row, index) =>
128	                differs(row) && (
129	                  <circle key={row.date} className="marker series-2" cx={x(index)} cy={y(row.analytics_net)} r="4.5" />
130	                ),
131	            )}
132	            {active &&
133	              SERIES.map((series) => (
134	                <circle key={series.key} className={`marker ${series.className}`} cx={x(hover)} cy={y(active[series.key])} r="4.5" />
135	              ))}
136	          </svg>
137	          {active && (
138	            <div className={`tooltip ${tooltipLeft > 60 ? "tooltip-left" : ""}`} style={{ left: `${tooltipLeft}%` }}>
139	              <div className="tooltip-title">{shortDate(active.date)}</div>
140	              {SERIES.map((series) => (
141	                <div key={series.key} className="tooltip-row">
142	                  <span className={`legend-line ${series.className}`} aria-hidden="true" />
143	                  <strong>{money(active[series.key], currency)}</strong>
144	                  <span className="muted">{series.label}</span>
145	                </div>
146	              ))}
147	              <div className="tooltip-row tooltip-delta">
148	                {differs(active)
149	                  ? `Analytics is ${signedMoney(active.analytics_net - active.source_net, currency)} against the source`
150	                  : "Analytics matches the source"}
151	              </div>
152	            </div>
153	          )}
154	        </div>
155	      )}
156	      <p className="muted chart-note">
157	        {mismatched === 0
158	          ? "The two lines coincide on every day shown: analytics matches the source."
159	          : `${mismatched} of ${rows.length} days differ. The lines coincide wherever analytics matches the source.`}
160	      </p>
161	    </div>
162	  );
163	}
