// Brand assets for the deck: the logo mark keyed onto transparency, and a mark + wordmark lockup.
//     NODE_PATH=<pptx deps>:<playwright deps> node lockup.js MARK.png OUTDIR
const path = require("path");
const sharp = require("sharp");
const { chromium } = require("playwright-core");

(async () => {
  const [markPath, outDir] = process.argv.slice(2);
  const { data, info } = await sharp(markPath).ensureAlpha().raw().toBuffer({ resolveWithObject: true });
  const bg = [7, 12, 36]; // the logo file's flat navy
  for (let i = 0; i < data.length; i += 4) {
    let a = Math.max(...[0, 1, 2].map((c) => (data[i + c] - bg[c]) / (255 - bg[c])));
    a = Math.max(0, Math.min(1, (a - 0.03) / 0.97));
    for (let c = 0; c < 3; c += 1) data[i + c] = a ? Math.max(0, Math.min(255, Math.round((data[i + c] - bg[c] * (1 - a)) / a))) : 0;
    data[i + 3] = Math.round(a * 255);
  }
  const mark = await sharp(data, { raw: info }).trim().png().toBuffer();
  await sharp(mark).toFile(path.join(outDir, "mark.png"));

  const browser = await chromium.launch({ channel: "chrome", headless: true });
  const page = await (await browser.newContext({ deviceScaleFactor: 3 })).newPage();
  await page.setContent(`<body style="margin:0;background:transparent"><div id="l" style="display:inline-flex;align-items:center;gap:14px;padding:4px 6px;font:700 46px/1 'Avenir Next','Helvetica Neue',Arial,sans-serif;letter-spacing:-.02em;color:#fff">
    <img src="data:image/png;base64,${mark.toString("base64")}" style="height:84px"><span>DataTrace<span style="color:#1fa0ff">Mind</span></span></div></body>`);
  await page.locator("#l").screenshot({ path: path.join(outDir, "lockup.png"), omitBackground: true });
  await browser.close();
  for (const f of ["mark.png", "lockup.png"]) { const m = await sharp(path.join(outDir, f)).metadata(); console.log(f, m.width, "x", m.height); }
})();

