// Screenshots of the console and the lab at phone and tablet widths, with API
// responses replayed from a snapshot so no backend is needed.
//   NODE_PATH=<dir with playwright-core> node shoot.cjs <label> [--only name,name] [--widths 375,768] [--dark]
const fs = require("fs");
const path = require("path");
const { chromium } = require("playwright-core");

const ROOT = __dirname;
const BASE = "http://127.0.0.1:5180";
const fx = (name) => JSON.parse(fs.readFileSync(path.join(ROOT, "fx", `${name}.json`), "utf8"));

function fixtures(variant) {
  const data = {
    "/api/agent/status": fx("agent_status"),
    "/api/metrics/summary": fx("metrics_summary"),
    "/api/incidents": fx("incidents"),
    "/api/incidents/INC-0001": fx("incident_detail"),
    "/api/pipeline/runs": fx("pipeline_runs"),
    "/api/demo/traffic": fx("demo_traffic"),
    "/api/transactions/live": fx("transactions_live"),
    "/api/audit": fx("audit"),
    "/api/scenarios": fx("scenarios"),
  };
  if (variant === "open") {
    // The same incident, wound back to the point where a human has to decide.
    const detail = data["/api/incidents/INC-0001"];
    detail.status = "awaiting_approval";
    detail.resolved_at = null;
    detail.proposal.status = "validated";
    detail.proposal.post_fix_result = null;
    detail.approvals = [];
    const cut = detail.events.findIndex((e) => e.event_type === "lifecycle" && e.status === "awaiting_approval");
    if (cut >= 0) detail.events = detail.events.slice(0, cut + 1);
    const row = data["/api/incidents"][0];
    row.status = "awaiting_approval";
    row.resolved_at = null;
    const metrics = data["/api/metrics/summary"];
    metrics.trust = "under_investigation";
    metrics.active_incident = { incident_id: row.incident_id, severity: row.severity, status: row.status, summary: row.summary };
    for (const side of Object.values(metrics.reconciliation.by_currency)) {
      side.within_tolerance = false;
      side.net_difference = Math.round(side.source.net * 0.15 * 100) / 100;
      side.analytics.net = side.source.net + side.net_difference;
      side.analytics.refunds = 0;
    }
    data["/api/agent/status"].access_code_required = true;
    data["/api/demo/traffic"].running = true;
  }
  return data;
}

const PAGES = {
  overview: "/#/overview",
  incidents: "/#/incidents",
  incident: "/#/incidents/INC-0001",
  audit: "/#/audit",
  lab: "/lab/",
};

// Elements that stick out past the right edge of the viewport without an
// ancestor that scrolls or clips them: what makes a page scroll sideways.
function findOverflow() {
  const limit = document.documentElement.clientWidth + 1;
  const clipped = (el) => {
    for (let node = el.parentElement; node && node !== document.body; node = node.parentElement) {
      const overflow = getComputedStyle(node).overflowX;
      if (overflow !== "visible") return true;
    }
    return false;
  };
  const found = [];
  for (const el of document.querySelectorAll("body *")) {
    const box = el.getBoundingClientRect();
    if (box.width === 0 || box.right <= limit || clipped(el)) continue;
    if (found.some((entry) => entry.el.contains(el))) continue;
    found.push({ el, text: `${el.tagName.toLowerCase()}.${String(el.className.baseVal ?? el.className).replace(/\s+/g, ".")} right=${Math.round(box.right)}` });
  }
  return { scrollWidth: document.documentElement.scrollWidth, viewport: limit - 1, offenders: found.slice(0, 8).map((e) => e.text) };
}

(async () => {
  const args = process.argv.slice(2);
  const label = args[0] || "run";
  const flag = (name) => (args.includes(name) ? args[args.indexOf(name) + 1] : null);
  const only = flag("--only")?.split(",");
  const widths = (flag("--widths") || "375").split(",").map(Number);
  const variants = (flag("--variants") || "open").split(",");
  const dark = args.includes("--dark");
  const outDir = path.join(ROOT, "shots", label);
  fs.mkdirSync(outDir, { recursive: true });

  const browser = await chromium.launch({ channel: "chrome", headless: true });
  const report = [];
  for (const variant of variants) {
    for (const width of widths) {
      const context = await browser.newContext({
        viewport: { width, height: width < 700 ? 780 : 900 },
        deviceScaleFactor: 1,
        hasTouch: width < 900,
        isMobile: width < 700,
        colorScheme: dark ? "dark" : "light",
      });
      const data = fixtures(variant);
      await context.route("**/api/**", (route) => {
        const url = new URL(route.request().url());
        const body = data[url.pathname];
        if (route.request().method() !== "GET" || body === undefined) return route.fulfill({ status: 404, json: { detail: "not in the snapshot" } });
        return route.fulfill({ json: body });
      });
      for (const [name, route] of Object.entries(PAGES)) {
        if (only && !only.includes(name)) continue;
        const page = await context.newPage();
        const errors = [];
        page.on("pageerror", (error) => errors.push(error.message));
        await page.goto(BASE + route, { waitUntil: "networkidle" });
        await page.waitForTimeout(500);
        const overflow = await page.evaluate(findOverflow);
        const file = path.join(outDir, `${name}-${variant}-${width}${dark ? "-dark" : ""}.png`);
        await page.screenshot({ path: file, fullPage: true });
        const flagged = overflow.scrollWidth > overflow.viewport ? "SIDEWAYS SCROLL" : "ok";
        report.push(`${name} ${variant} ${width}: ${flagged} (scrollWidth ${overflow.scrollWidth})${overflow.offenders.length ? "\n    " + overflow.offenders.join("\n    ") : ""}${errors.length ? "\n    page errors: " + errors.join(" | ") : ""}`);
        await page.close();
      }
      await context.close();
    }
  }
  await browser.close();
  console.log(report.join("\n"));
})();

