// Touch interactions on a phone-sized page: tapping the chart, scrolling past
// it, choosing a scenario in the stacked catalogue, and the favicon links.
//   NODE_PATH=<dir with playwright-core> node interact.cjs <label>
const fs = require("fs");
const path = require("path");
const { chromium } = require("playwright-core");

const ROOT = __dirname;
const BASE = process.env.BASE || "http://127.0.0.1:5180";
const fx = (name) => JSON.parse(fs.readFileSync(path.join(ROOT, "fx", `${name}.json`), "utf8"));
const DATA = {
  "/api/agent/status": fx("agent_status"),
  "/api/metrics/summary": fx("metrics_summary"),
  "/api/incidents": fx("incidents"),
  "/api/incidents/INC-0001": fx("incident_detail"),
  "/api/pipeline/runs": fx("pipeline_runs"),
  "/api/demo/traffic": fx("demo_traffic"),
  "/api/transactions/live": fx("transactions_live"),
  "/api/audit": fx("audit"),
  "/api/scenarios": fx("scenarios"),
};

(async () => {
  const outDir = path.join(ROOT, "shots", process.argv[2] || "interact");
  fs.mkdirSync(outDir, { recursive: true });
  const browser = await chromium.launch({ channel: "chrome", headless: true });
  const context = await browser.newContext({ viewport: { width: 375, height: 780 }, hasTouch: true, isMobile: true, deviceScaleFactor: 2 });
  await context.route("**/api/**", (route) => {
    const body = DATA[new URL(route.request().url()).pathname];
    return body === undefined ? route.fulfill({ status: 404, json: { detail: "not in the snapshot" } }) : route.fulfill({ json: body });
  });
  const log = [];

  // --- the chart ---
  const page = await context.newPage();
  page.on("pageerror", (error) => log.push(`page error: ${error.message}`));
  await page.goto(`${BASE}/#/overview`, { waitUntil: "networkidle" });
  log.push(`pointer coarse: ${await page.evaluate(() => matchMedia("(pointer: coarse)").matches)}`);
  const svg = page.locator(".chart-frame svg");
  await svg.scrollIntoViewIfNeeded();
  await page.evaluate(() => window.scrollBy(0, -160));
  const box = await svg.boundingBox();
  log.push(`chart drawn at ${Math.round(box.width)} x ${Math.round(box.height)}, viewBox ${await svg.getAttribute("viewBox")}`);
  log.push(`axis label size: ${await page.evaluate(() => { const t = document.querySelector(".chart .axis"); return t.getBoundingClientRect().height.toFixed(1) + "px tall, font " + getComputedStyle(t).fontSize; })}`);
  await page.touchscreen.tap(box.x + box.width * 0.82, box.y + box.height * 0.5);
  await page.waitForTimeout(300);
  const tip = page.locator(".tooltip");
  log.push(`tooltip after tap: ${(await tip.count()) ? "shown" : "missing"}`);
  if (await tip.count()) {
    const t = await tip.boundingBox();
    log.push(`tooltip box: left ${Math.round(t.x)} right ${Math.round(t.x + t.width)} (viewport 375); text: ${(await tip.innerText()).replace(/\n/g, " | ")}`);
  }
  await page.screenshot({ path: path.join(outDir, "chart-tap.png") });
  const before = await page.evaluate(() => window.scrollY);
  // A vertical swipe that starts on the chart must still scroll the page.
  const cdp = await context.newCDPSession(page);
  await cdp.send("Input.synthesizeScrollGesture", { x: Math.round(box.x + box.width / 2), y: Math.round(box.y + box.height / 2), yDistance: -260, gestureSourceType: "touch", speed: 1200 });
  await page.waitForTimeout(400);
  const after = await page.evaluate(() => window.scrollY);
  log.push(`vertical swipe on the chart scrolled the page by ${after - before}px; tooltip now ${(await tip.count()) ? "shown" : "dismissed"}`);

  // --- the scenario catalogue ---
  const lab = await context.newPage();
  lab.on("pageerror", (error) => log.push(`lab page error: ${error.message}`));
  await lab.goto(`${BASE}/lab/`, { waitUntil: "networkidle" });
  const row = lab.locator(".scenario-row", { hasText: "DS-07" });
  await row.scrollIntoViewIfNeeded();
  await lab.waitForTimeout(200);
  const y0 = await lab.evaluate(() => window.scrollY);
  await row.tap();
  await lab.waitForTimeout(1200);
  const state = await lab.evaluate(() => {
    const detail = document.getElementById("scenario-detail");
    return { scrollY: window.scrollY, detailTop: Math.round(detail.getBoundingClientRect().top), heading: detail.querySelector("h2").textContent };
  });
  log.push(`chose DS-07: page moved ${Math.round(state.scrollY - y0)}px, detail top now at ${state.detailTop}px, heading "${state.heading}"`);
  await lab.screenshot({ path: path.join(outDir, "scenario-chosen.png") });

  // --- the tab icon ---
  for (const route of ["/", "/lab/"]) {
    const p = await context.newPage();
    await p.goto(BASE + route, { waitUntil: "domcontentloaded" });
    const links = await p.evaluate(() => [...document.querySelectorAll('link[rel~="icon"], link[rel="apple-touch-icon"]')].map((l) => l.href));
    for (const href of links) {
      const res = await p.request.get(href);
      log.push(`${route} -> ${new URL(href).pathname}: ${res.status()} ${res.headers()["content-type"]} ${(await res.body()).length} bytes`);
    }
    await p.close();
  }
  await browser.close();
  console.log(log.join("\n"));
})();

