+/* A table too wide for its card scrolls sideways. A shadow shows at an edge
+   while more of the table lies beyond it, and is covered once that end is reached. */
+.table-scroll {
+  overflow-x: auto;
+  background:
+    linear-gradient(to right, var(--surface) 40%, transparent) left / 36px 100% no-repeat local,
+    linear-gradient(to left, var(--surface) 40%, transparent) right / 36px 100% no-repeat local,
+    radial-gradient(farthest-side at 0 50%, var(--scroll-shadow), transparent) left / 12px 100% no-repeat scroll,
+    radial-gradient(farthest-side at 100% 50%, var(--scroll-shadow), transparent) right / 12px 100% no-repeat scroll;
+}
